-- Generated by scripts/build_compiled.py from src/fraudrules/rules/money-mule/mu-003-fan-out-new-payees.yaml. Do not edit.
-- MU-003 Funds sent to several first-time payees within two days
SELECT
  'MU-003' AS rule_id,
  'transactions' AS anchor_table,
  a.id AS anchor_id
FROM transactions AS a
JOIN transactions AS b
  ON b.account_id = a.account_id AND b.ts <= a.ts AND b.ts > a.ts - 172800
WHERE
  (
    a.direction = 'out'
    AND a.counterparty_new = 1
    AND a.channel IN ('ach', 'wire', 'rtp', 'p2p')
  )
  AND (
    b.direction = 'out'
    AND b.counterparty_new = 1
    AND b.channel IN ('ach', 'wire', 'rtp', 'p2p')
  )
GROUP BY
  a.id
HAVING
  (
    COUNT(DISTINCT b.counterparty_id) >= 4 AND SUM(b.amount_cents) >= 500000
  );
